"""Source-authored 2016 Paper 3 B1 reconstruction (museum documents)."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent / 'layouts'
def b(en, zh): return f'<div class="bilingual"><p lang="en">{escape(en)}</p><p class="translation" lang="zh-Hant">{escape(zh)}</p></div>'
def put(n, body): (ROOT / f'2016-b1-page-{n:02}.html').write_text(body.rstrip()+'\n', encoding='utf-8')
def inp(key,label): return f'<input data-note="10-{key}" aria-label="{escape(label,quote=True)}">'

put(1,(ROOT/'2014-b1-page-01.html').read_text().replace('2014','2016'))
toc=[(3,'Listening note-taking sheet for podcast Nosing Around'),(4,'Email from Lara Gau to Indy Wong'),(5,'Article from The Hong Kong Review'),(6,'Minutes from museum staff meeting'),(7,'Email exchange between Limahl Howard and Lara Gau'),(8,'Question Wizard online survey results of museum visitors'),(8,'Lok and Partners’ interim report'),(9,'Museum Staff Manual'),(9,'Part-time student assistants’ feedback from summer 2015')]
situation=[('You are Indy Wong. You are a museum assistant for Lara Gau at the Hong Kong Social History Museum. Lara has a few things she wants you to do to help out.','你是 Indy Wong，在香港社會歷史博物館擔任 Lara Gau 的助理。Lara 有幾項工作需要你協助。'),('You will listen to an interview between Patty Leung and Dr Jack Jones for the podcast Nosing Around.','你將聆聽 Patty Leung 訪問 Jack Jones 博士的 Nosing Around 播客。'),('Before the recording is played, you will have five minutes to study the Question-Answer Book and the Data File to familiarize yourself with the situation and the tasks.','錄音播放前，你有五分鐘閱讀問答冊和資料檔，熟悉情境和任務。'),('Complete the tasks by following the instructions in the Question-Answer Book and on the recording. You will find all the information you need in the Question-Answer Book, the Data File and on the recording. As you listen you can make notes on page 3 of the Data File.','依照問答冊和錄音的指示完成任務。所需資料在問答冊、資料檔及錄音中。聆聽時可在資料檔第 3 頁記筆記。'),('You now have five minutes to familiarize yourself with the Question-Answer Book and the Data File.','現在有五分鐘熟悉問答冊和資料檔。')]
put(2,'<section class="recreated-page situation-page" aria-label="2016 Part B situation and contents"><div class="situation-box"><h2>Part B</h2><h3>Situation</h3>'+''.join(b(*x) for x in situation)+'</div><div class="contents-box"><h3>Contents</h3><ol>'+''.join(f'<li><a href="#page-{page}">{escape(title)} <span>{page}</span></a></li>' for page,title in toc)+'</ol></div></section>')
notes=[('Social History Museum (and directions)','社會歷史博物館及前往路線'),('Wang Chung Traditional Farmhouse and Village','王涌傳統農舍及村莊'),('Dr Jones’ Talk','Jones 博士的講座'),('Chang Yee Tak Plough','張義德犁')]
put(3,'<section class="recreated-page conference-notes" aria-label="Nosing Around podcast notes"><h2>Listening note-taking sheet for podcast <em>Nosing Around</em></h2><div class="notes-form-body">'+''.join(f'<h3>{escape(en)}</h3><p class="translation" lang="zh-Hant">{escape(zh)}</p><textarea data-note="3-{i}" rows="6" aria-label="Notes: {escape(en,quote=True)}"></textarea>' for i,(en,zh) in enumerate(notes,1))+'</div></section>')
lara=[('Hi Indy','Indy：'),('How are things in Hong Kong? Mexico is great! I’ll tell you all about it when I get back. While I am away, I’ve got three things I need you to do.','香港那邊如何？墨西哥很好！回來再告訴你。我不在期間，有三件事請你處理。'),('The first thing I want you to do is complete the 1980s Exhibition flyer. You might want to look at the Hong Kong Review and the minutes of the staff meeting as well as your notes from the podcast. Note that we got positive feedback in The Hong Kong Review so you should be able to find another quote from there to put at the top of the flyer (4 words).','首先完成 1980 年代展覽傳單。參考《香港評論》、員工會議紀錄和播客筆記。評論中有正面評語，請找出另一句四字引言放在傳單上方。'),('Secondly, you need to write the progress report for Dr Jones on the new museum café. Include the following information: the new name for the café, full details about the new location of the café, what work has been completed so far, including the children’s play area outside the café. I’ll forward you my emails with Mr Howard about this. You might want to look at the minutes of the last meeting as well as the Question Wizard results and Mr Lok’s interim report.','其次，為 Jones 博士撰寫新博物館咖啡室的進度報告，交代新名稱、新位置的完整資料，以及咖啡室和戶外兒童遊樂區的工程進度。可參考我和 Howard 先生的電郵、會議紀錄、問卷結果及 Lok 先生的中期報告。'),('Finally, can you write a letter to Ms Pollitti, the Careers Mistress at St Scritti’s School, and tell her about the part-time student assistant positions. We want to attract pupils from this excellent school. You will need to explain what a social history museum is as well as outline the details of the position. See also the minutes of the last meeting and the relevant page in the staff manual to help you. You should include positive feedback from previous student assistants to show why it will be a good experience.','最後請寫信給 St Scritti’s School 的就業輔導老師 Pollitti 女士，介紹兼職學生助理職位。解釋社會歷史博物館的性質及職位詳情，並引用過往助理的正面回饋。')]
put(4,'<section class="recreated-page email-document" aria-label="Email from Lara Gau to Indy Wong"><h2>Email from Lara Gau to Indy Wong</h2><div class="email-window"><div class="email-headers"><div><strong>To:</strong> Indy Wong</div><div><strong>From:</strong> Lara Gau</div><div><strong>Sent:</strong> Fri 8 April 2016 3:14 AM</div><div><strong>Subject:</strong> Things to do</div></div><div class="email-content">'+''.join(b(*x) for x in lara)+'<p>Lara</p></div></div></section>')
article=[('Well, my immediate reaction when my editor told me to review a museum rather than my usual restaurant reviews was ‘Oh no! Not a boring old museum!’ But I had never been to the new Hong Kong Social History Museum, so I tried to keep an open mind....','編輯叫我評論博物館而非平常的餐廳時，我第一反應是「不要！無聊的舊博物館！」但我從未到訪新開的香港社會歷史博物館，於是嘗試保持開放心態。'),('The best part for me at the museum was the “Household of the 80s”. There are lots of rooms you can walk around and you get to try out different things. My favourite room was the “TV lounge”. I got to watch TV. Some old TV programmes I remembered watching when I was a kid. I also really enjoyed playing around on an old “Spectrum” computer and seeing if I could top my high scores on some old games.','最精彩的是「八十年代家居」展區。可以走進不同房間親身體驗。我最喜歡電視廳，看到童年看過的節目，也很享受玩舊式 Spectrum 電腦遊戲。'),('Another great thing about the Social History Museum is that it is really close to South Point MTR.','另一好處是博物館很靠近 South Point 港鐵站。'),('Overall, I have to say this was an excellent day out.','總括而言，這是很棒的一日遊。')]
put(5,'<section class="recreated-page museum-review" aria-label="Hong Kong Review museum article"><h2>Article from <em>The Hong Kong Review</em></h2><article class="review-sheet"><h3>How we used to live in the 80s: The Hong Kong Social History Museum</h3>'+''.join(b(*x) for x in article)+'<p>Rating: ☀ ☀ ☀ ☀ ½</p></article></section>')
minutes=[('Response to “How we used to live in the 1980s” Exhibition',[('Dr Jones was pleased to announce that the exhibition has been very successful so far. The reviews in the newspapers have been very positive, especially about the household of the 1980s. Visitor feedback showed that the bathroom was the most popular room. People reported enjoying smelling the soaps and tasting the toothpaste as top highlights.','Jones 博士表示展覽成績很好，報章尤其讚賞八十年代家居。訪客最喜歡浴室，特別是聞香皂和品嘗牙膏。')]),('Update on the museum café',[('Dr Jones was very concerned that Lara had not yet completed a progress report about the new café before leaving for Mexico. Lara said the final report would be completed by Indy.','Jones 博士擔心 Lara 赴墨西哥前尚未完成新咖啡室進度報告；Lara 說由 Indy 完成。'),('She informed the meeting that Minton’s had finished making the tables and chairs and that the expected delivery date was April 27. She added that Mr Lok, the builders, had promised to send an interim report later that day.','Minton’s 已完成桌椅，預計 4 月 27 日送達；承建商 Lok 先生當天稍後會提交中期報告。')]),('Part-time student assistants',[('Dr Jones has agreed to the request to hire three part-time assistants this year. They will work four days a week from July to August.','Jones 博士同意聘請三名兼職助理，於七至八月每週工作四天。'),('Limahl enquired whether they would help on a daily basis in the café. The meeting rejected this idea but agreed for them to assist when it is very busy.','會議否決讓他們每日在咖啡室工作的建議，但同意在繁忙時協助。'),('It was agreed to increase the hourly rate to $38.','時薪將增至 38 元。')]),('Update on talk',[('Dr Jones confirmed that he would give a talk at the museum. Exact date and time to be confirmed. He added that the talk would be about the changes in the traditional way of life on farms in the New Territories since the 1980s.','Jones 博士會在館內演講，日期時間待定，主題是八十年代以來新界農場傳統生活方式的變化。')])]
meeting='<section class="recreated-page meeting-minutes museum-minutes" aria-label="Museum staff meeting minutes"><h2>Minutes from museum staff meeting</h2><div class="meeting-sheet"><h3>Staff meeting of the Hong Kong Social History Museum</h3><dl class="meeting-meta"><dt>Date:</dt><dd>Tues. April 5, 2016</dd><dt>Venue:</dt><dd>Museum Seminar Room 2</dd><dt>Chairperson:</dt><dd>Dr Jack Jones, Director</dd><dt>In Attendance:</dt><dd>Limahl Howard, Building Management Director<br>Lara Gau, Public Relations and Retail<br>Xu Xinpeng, Facilities</dd><dt>Secretary:</dt><dd>Cindy Lau</dd></dl><h3>Minutes of Meeting</h3><ul>'+''.join('<li><h4>'+escape(title)+'</h4>'+''.join(b(*x) for x in pars)+'</li>' for title,pars in minutes)+'</ul></div></section>'
put(6,meeting)

thread=[('To: Lara Gau','From: Limahl Howard','Sent: Fri 1 April 2016 11:33 AM','Subject: Re: Progress Report',[('Lara','Lara：'),('You can view the online results about the vote on the new café name and children’s play area facilities at Question Wizard: http://questionnwizard.com/hkmuscafe/Quodsusg','新咖啡室名稱及兒童遊樂區設施的投票結果，可在 Question Wizard 網站查閱。'),('The downside of the change of venue is the space. So we can only have the two most popular play area facilities.','更換地點的缺點是空間有限，因此只能設置得票最高的兩項遊樂設施。')],'Limahl'),('To: Limahl Howard','From: Lara Gau','Sent: Thurs 31 March 2016 10:47 AM','Subject: Re: Progress Report',[('Dear Limahl','Limahl：'),('Thanks. Another thing I mentioned on the phone was I need to know what the voters decided about the facilities for the kids’ play area and what they chose for the new name for the café.','謝謝。我在電話中提過，還需要知道投票者為兒童遊樂區選了甚麼設施，以及咖啡室的新名稱。')],'Lara'),('To: Lara Gau','From: Limahl Howard','Sent: Thurs 31 March 2016 10:26 AM','Subject: Progress Report',[('Hi Lara','Lara：'),('Here’s the information about the building work you requested on the phone just now. The main thing I suppose is that the café won’t be on the ground floor. As you will remember, the safety report said the ground floor’s too close to the road – and dangerous for children. Plus, there’s just too much air pollution from the traffic. Oh and the noise (from the traffic). So that’s why it was decided that it’s going to go on the museum rooftop instead.','以下是你剛才來電索取的工程資料。咖啡室不會設在地下，因地下太接近馬路，對兒童有危險，也有交通造成的空氣和噪音污染。因此改設在博物館天台。')],'Limahl')]
def mail(headers,paras,sign):
    return '<div class="email-window"><div class="email-headers">'+''.join(f'<div><strong>{escape(h.split(":",1)[0])}:</strong>{escape(h.split(":",1)[1])}</div>' for h in headers)+'</div><div class="email-content">'+''.join(b(*p) for p in paras)+f'<p>{escape(sign)}</p></div></div>'
put(7,'<section class="recreated-page museum-thread" aria-label="Limahl Howard and Lara Gau email exchange"><h2>Email exchange between Limahl Howard and Lara Gau</h2>'+''.join(mail(row[:4],row[4],row[5]) for row in thread)+'</section>')

names=[('The Rubik Cubical',234),('Spandau Café',567),('Café at the End of the Universe',123),('Snack Man',234),('Foodloose',45)]
facilities=[('Slides',234),('Kids’ climbing wall',576),('Witch’s hat',144),('Swings',786),('Roundabout',55)]
