put(8,'<section class="recreated-page museum-survey" aria-label="Question Wizard survey and Lok interim report"><h2>Question Wizard online survey results of museum visitors</h2><div class="survey-browser"><div class="browser-strip">Question Wizard · File　Edit　View　Go　Bookmarks　Tools　Help</div><div class="browser-strip">http://questionnwizard.com/hkmuscafe/Quodsusg</div><div class="survey-tables">'+survey_table('Suggested names','Suggested name',names)+survey_table('Suggested play area facilities','Facility',facilities)+'</div></div><p class="translation" lang="zh-Hant">咖啡室名稱以 Spandau Café 得票最多（567 票）；遊樂設施以鞦韆（786 票）及兒童攀石牆（576 票）得票最多。</p><h2>Lok and Partners’ interim report</h2><div class="email-window"><div class="email-headers"><div><strong>To:</strong> Lara Gau</div><div><strong>From:</strong> Lok and Partners</div><div><strong>Sent:</strong> Tues 5 April 2016 4:33 PM</div><div><strong>Subject:</strong> Interim Report on HK Social History Museum work</div></div><div class="email-content">'+b('Dear Ms Gau,','Gau 女士：')+b('See the interim report below on the building work at the museum as requested:','按要求，以下是博物館工程的中期報告：')+report_table+b('Please contact me on WhatsApp on 9654376 if you have any enquiries.','如有疑問，請透過 WhatsApp 9654376 聯絡我。')+'<p>Regards,<br>Jimmie Lok<br>Lok and Partners Ltd</p></div></div></section>')

feedback=[('Thinking back on what happened while I worked there I feel teamwork was what I really developed in.','回想在這裏工作的經歷，我覺得最有進步的是團隊合作。'),('It was okay at times. A bit boring though.','有時還可以，不過有點無聊。'),('The pay was terrible but having said that as a communicator I’m so much better than I was before.','薪酬很差，但我的溝通能力確實比以前好得多。')]
put(9,'<section class="recreated-page museum-manual" aria-label="Museum staff manual and student feedback"><h2>Museum Staff Manual</h2><div class="manual-sheet"><h3>Section 4.5: Part-time Student Assistant Staff</h3><h4>4.5.1 Main Duties</h4>'+b('Part-time assistants are permitted to do the following:','兼職助理可執行以下工作：')+'<ul><li>assist visitors</li><li>clean display items (after training)</li></ul><p class="translation" lang="zh-Hant">協助訪客；接受培訓後清潔展品。</p><h4>4.5.2 Working Hours</h4>'+b('Assistants must not work more than 4 hours per day on any day.','助理每日工作不可超過四小時。')+'</div><h2>Part-time student assistants’ feedback from summer 2015</h2><div class="feedback-sheet">'+''.join(f'<div class="feedback-item"><strong>({i})</strong>{b(en,zh)}</div>' for i,(en,zh) in enumerate(feedback,1))+'</div><p class="end-note">THIS IS THE LAST PAGE OF THE PART B1 DATA FILE</p></section>')

flyer='<div class="museum-flyer"><h4>The Hong Kong Social History Museum Presents:<br>How we used to live in the 1980s</h4><p class="flyer-tagline">Come and experience how people lived in the 1980s in our exciting new exhibition!</p><div class="flyer-quotes"><strong>“A wonderful experience” – Hong Kong Times</strong><label>“'+inp('quote','Four-word quote from The Hong Kong Review')+'” – '+inp('quote-source','Quote source')+'</label></div><div class="flyer-columns"><section><h5>TALKS</h5><label>Title: '+inp('talk-title','Talk title')+'</label><label>Speaker: '+inp('speaker','Talk speaker')+'</label><label>Contents of Talk: '+inp('talk-content','Talk content')+'</label><label>Date &amp; Time: '+inp('talk-time','Talk date and time')+'</label></section><section><h5>HOUSEHOLD OF THE 1980s</h5><ul><li><strong>Room #1: The bedroom.</strong><p>Activities: Admire posters, listen to some 80s pop music like “Hot Topic” and “Lena Nutshell” and read classic story books and comics.</p></li><li>Room #2: '+inp('room2','Second room name')+'<p>Activities: '+inp('room2-activity','Second room activities')+'</p></li><li>Room #3: '+inp('room3','Third room name')+'<p>Activities: '+inp('room3-activity','Third room activities')+'</p></li></ul></section></div><label>Directions for getting to the museum from the new MTR station<textarea rows="3" data-note="10-directions" aria-label="Directions from the new MTR station"></textarea></label></div>'
put(10,'<section class="recreated-page answer-book museum-flyer-answer" aria-label="2016 B1 QAB page 1"><div class="answer-book-header"><span>HKDSE 2016 · ENGLISH LANGUAGE · PAPER 3 PART B1 · Question-Answer Book</span><strong>B1</strong></div><h3>Task 5: Exhibition flyer <small>(18 marks)</small></h3>'+b('Complete the 1980s Exhibition flyer below using information from the B1 Data File and your notes.','利用乙部一資料檔及筆記完成八十年代展覽傳單。')+flyer+'<p class="answer-end">END OF TASK 5</p></section>')

def essay(page,key,title,zh,lead='',height=680):
    cid=f'2016-b1-{page}-{key}'
    return f'<section class="recreated-page answer-book" aria-label="2016 B1 QAB page {page-9}"><h3>{escape(title)}</h3>{lead}<p class="translation" lang="zh-Hant">{escape(zh)}</p><label class="answer-field" for="{cid}">{escape(title)}</label><textarea class="answer-box" id="{cid}" data-note="{page}-{key}" data-count-id="{cid}" style="min-height:{height}px" aria-label="{escape(title,quote=True)}"></textarea><p class="answer-count" data-count-for="{cid}">0 words</p>'
put(11,essay(11,'report','Task 6: Progress report (18 marks)','任務 6：新博物館咖啡室進度報告，約 120 字。',b('Write a progress report on the new museum café using information from the B1 Data File. Write around 120 words.','利用乙部一資料檔撰寫新博物館咖啡室進度報告，約 120 字。'))+'</section>')
put(12,essay(12,'report-cont','Task 6: Progress report, continued','任務 6：進度報告續頁。',height=300)+'<p class="answer-end">END OF TASK 6</p><h3>Task 7: Letter <small>(18 marks)</small></h3>'+b('Write a letter to the Careers Mistress at St. Scritti’s School using information from the Data File and your notes. There is no need to write the address or date. Write around 150 words.','利用資料檔及筆記寫信給 St. Scritti’s School 的就業輔導老師。毋須寫地址或日期，約 150 字。')+'<label class="answer-field" for="2016-b1-12-letter">Task 7 letter</label><textarea class="answer-box" id="2016-b1-12-letter" data-note="12-letter" data-count-id="2016-b1-12-letter" style="min-height:420px" aria-label="Task 7 letter"></textarea><p class="answer-count" data-count-for="2016-b1-12-letter">0 words</p></section>')
put(13,essay(13,'letter-cont','Task 7: Letter, continued','任務 7：書信續頁。',height=720)+'<p class="answer-end">END OF TASK 7<br>END OF PART B1</p></section>')
